address from,
address to,
uint256 value
) internal override {

if (!isValidTokenId(value)) {
super._update(from, to, value);
}

if (to == address(this) || to == erc721) {
transform(value);
} else {
if (isValidTokenId(value)) {

if (from != address(0)) {
require(
iERC721CheckAuth(erc721).isAuthorized(
from,
msg.sender,
value
),
"P404: not authorized"
);
}
IERC721(erc721).safeTransferFrom(from, to, value);
}
}
}

