uint256 realcost = _mint * MINT_PRICE;

require(mintedAmount[msg.sender] + realcost <= MAX_MINT_VALUE, "P404: exceed max mint value");
require(nftMinted + _mint <= MAX_NFT_MINT, "P404: exceed max mint");

